 +UM_arrow(340,Y(3)+84,380,Y(3)+84,INK,3)+UM_box(384,Y(3)+54,130,60,{fill:'#FFFFFF',st:BLU,sw:3,r:10})+UM_T(449,Y(3)+80,'sampler',{fs:22,fw:800,a:'middle',fill:BLU})+UM_T(449,Y(3)+104,UM_FS,{fs:22,a:'middle',fill:BLU})
